        STAA    $0D06,Z
        JSR     EgrSparkCalc
        STAA    >CalcSparkD08,Z
        JSR     CoolantSparkCalc
        STAA    >CalcSparkD07,Z
        JSR     AfterStartSpark
        STAA    >CalcSparkD0A,Z
        JSR     SparkHook
        STAA    >CalcSparkD09,Z
        JSR     Sub_1F13E
        STAA    $0405,Z
        JSR     Sub_1DF54
