        STAA    $0D0D,Z
        JSR     TipInSparkControl
        STAA    >CalcSparkD10,Z
        JSR     HighSpeedSparkFlag
        STAA    $0D0B,Z
        JSR     Sub_1E724
        BRCLR   >SparkFlags3,Z,#$01,L1D094               ; bit 0: spark period above $5DC0: low rpm (Isr_GPT_IC1, SparkEventCalc)
        JSR     IdleSparkCalc
L1D094:
        LDAB    $0D03,Z
        SXT
        TDE
        LDAB    $0D05,Z
        SXT
        ADE
        LDAB    $0D06,Z
        SXT
        ADE
