        SXT
        ADE
        LDAB    >CalcSparkD07,Z
        SXT
        ADE
        LDAB    >CalcSparkD0A,Z
        SXT
        ADE
        LDAB    >CalcSparkD09,Z
        SXT
        ADE
        LDAB    $0405,Z
        SXT
        ADE
        LDAB    >CalcSparkD0C,Z
        SXT
        ADE
        LDAB    $0F58,Z
        SXT
        ADE
        LDAB    $0D4C,Z
        SXT
        SDE
        LDAB    $0D0D,Z
        SXT
