        CPD     #$FF80
        BGE     L1D128
        LDAB    #$80
L1D128:
        TBA
        STAA    $06D3,Z
        BRCLR   >FuelPulseOptFlags,Z,#$02,L1D13A
        LDAA    $0C51,Z
        BRA     L1D15A
L1D13A:
        LDAB    >ThrottleState,Z
        ANDB    #$01
        ORAB    >DashpotTimer,Z
        BNE     L1D150
        LDAB    >FaultSet02,Z
        BITB    #$C0
        BNE     L1D156
        BRA     L1D15A
L1D150:
