SparkHook:
        AIS     #$FC
        TSY
        BRCLR   >Options0338,#$20,L1D184                 ; bit 5: knock enrichment on (KnockEnrichment, SparkHook)
        LDAA    >CoolantTemp,Z
        CMPA    >SparkHookCoolantMin
